import React, { useState } from "react";
import { motion } from "framer-motion";
import { Play, Factory, Palette, Truck, Heart } from "lucide-react";

const FEATURES = [
  {
    icon: Factory,
    title: "Premium Manufacturing",
    description: "State-of-the-art facility with skilled artisans crafting each piece with precision and care."
  },
  {
    icon: Palette,
    title: "Color Customization",
    description: "Wide range of colors and patterns. We match your event theme perfectly."
  },
  {
    icon: Truck,
    title: "Pan India Delivery",
    description: "Safe packaging and timely delivery across India with tracking."
  },
  {
    icon: Heart,
    title: "Quality Promise",
    description: "Every piece inspected before dispatch. 100% quality guarantee."
  },
];

const PROCESS = [
  { step: "01", title: "Select Products", desc: "Browse our collections and choose your fabrics" },
  { step: "02", title: "Share Requirements", desc: "Tell us colors, quantities, measurements" },
  { step: "03", title: "Get Quote", desc: "Receive personalized pricing within hours" },
  { step: "04", title: "Order Confirmed", desc: "Production starts with care" },
  { step: "05", title: "Safe Delivery", desc: "Carefully packed and delivered to your door" },
];

export default function BehindScenes() {
  return (
    <section className="py-20 md:py-28" style={{ background: "linear-gradient(180deg, #faf8f5 0%, #ffffff 100%)" }}>
      <div className="px-6 md:px-12 lg:px-24">

        {/* Section Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="text-center mb-16"
        >
          <p className="text-xs tracking-[0.3em] uppercase mb-3" style={{ color: "#d4af37" }}>Behind The Scenes</p>
          <h2 className="serif text-3xl md:text-4xl mb-4" style={{ color: "#1a080a" }}>
            How We <span style={{ color: "#d4af37", fontStyle: "italic" }}>Craft Excellence</span>
          </h2>
        </motion.div>

        {/* Features Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-16">
          {FEATURES.map((feature, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: i * 0.1 }}
              className="p-6 rounded-xl text-center"
              style={{ background: "white", border: "1px solid rgba(212,175,55,0.2)", boxShadow: "0 4px 20px rgba(212,175,55,0.08)" }}
            >
              <div className="w-14 h-14 rounded-full mx-auto mb-4 flex items-center justify-center" style={{ background: "rgba(212,175,55,0.1)" }}>
                <feature.icon size={28} color="#d4af37" />
              </div>
              <h3 className="text-lg font-semibold mb-2" style={{ color: "#1a080a" }}>{feature.title}</h3>
              <p className="text-sm" style={{ color: "rgba(26,8,10,0.6)", lineHeight: 1.6 }}>{feature.description}</p>
            </motion.div>
          ))}
        </div>

        {/* Process Timeline */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="text-center mb-12"
        >
          <h3 className="serif text-2xl mb-8" style={{ color: "#1a080a" }}>
            Our Simple <span style={{ color: "#d4af37", fontStyle: "italic" }}>5-Step Process</span>
          </h3>

          <div className="flex flex-wrap justify-center gap-4">
            {PROCESS.map((p, i) => (
              <React.Fragment key={p.step}>
                <motion.div
                  initial={{ opacity: 0, scale: 0.8 }}
                  whileInView={{ opacity: 1, scale: 1 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: i * 0.1 }}
                  className="text-center"
                >
                  <div className="w-16 h-16 rounded-full mx-auto mb-3 flex items-center justify-center text-xl font-bold" style={{ background: "linear-gradient(135deg, #d4af37, #f4d77a)", color: "#1a080a" }}>
                    {p.step}
                  </div>
                  <p className="font-semibold text-sm mb-1" style={{ color: "#1a080a" }}>{p.title}</p>
                  <p className="text-xs max-w-[120px]" style={{ color: "rgba(26,8,10,0.5)" }}>{p.desc}</p>
                </motion.div>

                {i < PROCESS.length - 1 && (
                  <div className="hidden md:flex items-center">
                    <div className="w-8 h-px" style={{ background: "linear-gradient(90deg, #d4af37, transparent)" }} />
                  </div>
                )}
              </React.Fragment>
            ))}
          </div>
        </motion.div>

        {/* CTA */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="text-center"
        >
          <button
            onClick={() => window.open("https://wa.me/919888919983?text=Hi!%20I'd%20like%20to%20know%20more%20about%20D%20SAJAWAT's%20process", "_blank")}
            className="btn-gold px-10 py-4"
          >
            <Play size={18} />
            Learn More About Our Process
          </button>
        </motion.div>
      </div>
    </section>
  );
}
